@@ -0,0 +1,13 @@
+/**
+ * Sets an own, writable property on an error instance. Plain assignment throws
+ * in strict mode when `Error.prototype` is frozen (inherited `name`/`message`
+ * become read-only), so define the own property explicitly instead.
+ */
+export function setErrorProperty(error: Error, key: 'name' | 'message', value: string) {
+	Object.defineProperty(error, key, {
+		value,
+		writable: true,
+		configurable: true,
+		enumerable: false,
+	});
+}
