@@ -0,0 +1,45 @@
+import { NodeApiError } from '../../src/errors/node-api.error';
+import { NodeOperationError } from '../../src/errors/node-operation.error';
+import { WorkflowActivationError } from '../../src/errors/workflow-activation.error';
+import { WorkflowOperationError } from '../../src/errors/workflow-operation.error';
+import { ManualExecutionCancelledError } from '../../src/errors/execution-cancelled.error';
+import type { INode } from '../../src/interfaces';
+
+// Freezing is irreversible, so this lives in its own file (vitest isolates files).
+describe('errors with a frozen Error.prototype', () => {
+	const node: INode = {
+		id: '1',
+		name: 'Node',
+		type: 'n8n-nodes-base.set',
+		typeVersion: 1,
+		position: [0, 0],
+		parameters: {},
+	};
+
+	beforeAll(() => {
+		Object.freeze(Error.prototype);
+	});
+
+	it('constructs NodeApiError with an empty message', () => {
+		const error = new NodeApiError(node, { foo: 'bar' }, { httpCode: '404' });
+		expect(error.name).toBe('NodeApiError');
+		expect(error.message).toBe('The resource you are requesting could not be found');
+	});
+
+	it('constructs NodeOperationError with a message override', () => {
+		const error = new NodeOperationError(node, new Error('x'), { message: 'custom' });
+		expect(error.name).toBe('NodeOperationError');
+		expect(error.message).toBe('custom');
+	});
+
+	it('constructs the other execution errors', () => {
+		expect(new WorkflowOperationError('boom').name).toBe('WorkflowOperationError');
+		expect(new ManualExecutionCancelledError('1').message).toBe(
+			'The execution was cancelled manually',
+		);
+		const cause = new WorkflowOperationError('inner');
+		const error = new WorkflowActivationError('outer', { cause });
+		expect(error.message).toBe('outer');
+		expect(error.name).toBe('WorkflowActivationError');
+	});
+});
